import { createRequire } from 'node:module'
import { writeFile } from 'node:fs/promises'
if (process.argv.some(arg=>arg.endsWith('test/pardner-connection-ui.test.js'))) await observe()
async function observe(){
 const require=createRequire(process.cwd()+'/package.json')
 const {chromium,webkit}=require('playwright')
 const records=[];let sequence=0,browserId=0,pageId=0,flushQueue=Promise.resolve()
 const target=process.env.PARDNER_FULL_UI_TRACE_DIRECTORY+'/observer-'+process.pid+'.json'
 const emit=event=>records.push({sequence:++sequence,at:Date.now(),...event})
 const flush=()=>{const snapshot=records.slice();flushQueue=flushQueue.then(()=>writeFile(target,JSON.stringify(snapshot),{mode:0o600})).catch(()=>{});return flushQueue}
 const safeUrl=url=>{try{const u=new URL(url);return {pathname:u.pathname,hasPair:new URLSearchParams(u.hash.slice(1)).has('pair')}}catch{return {pathname:'unavailable',hasPair:false}}}
 process.once('beforeExit',()=>{void flush()})
 for(const engine of [chromium,webkit]){
  const launch=engine.launch.bind(engine)
  engine.launch=async (...args)=>{
   const browser=await launch(...args),bid=++browserId
   emit({phase:'browser-launched',browserId:bid,engine:engine.name(),version:browser.version()})
   if(engine!==webkit)return browser
   const pendingCaptures=new Set(),newContext=browser.newContext.bind(browser)
   browser.newContext=async (...args)=>{
    const context=await newContext(...args)
    const pages=new WeakMap()
    await context.exposeBinding('__pardnerFullPairDiagnostic',({page},event)=>{
     const p=pages.get(page);if(!p)return
     p.browserState={...p.browserState,...event};if(event.phase==='render-state'||event.phase==='hashchange')p.lastRender={...event,receivedAt:Date.now()}
     if(event.phase.startsWith('ws-'))p.lastSocket={...event,receivedAt:Date.now()}
     emit({source:'page',browserId:bid,pageId:p.id,...event})
    })
    await context.addInitScript(()=>{
   const send=(phase,data={})=>{void window.__pardnerFullPairDiagnostic({phase,browserAt:performance.now(),documentAt:performance.timeOrigin,...data}).catch(()=>{})}
   if(window.__pardnerFullPairObserver){send('observer-reentry');return}
   const hasPair=()=>new URLSearchParams(location.hash.slice(1)).has('pair')
   const credentialPresent=()=>{try{return Object.keys(localStorage).filter(k=>k.endsWith(':credential')).some(k=>Boolean(localStorage.getItem(k)))}catch{return null}}
   const state=()=>({documentAt:performance.timeOrigin,readyState:document.readyState,hasPair:hasPair(),credentialPresent:credentialPresent(),savedVisible:Array.from(document.querySelectorAll('.save-status')).some(e=>e.textContent==='Saved locally · synced'),saveStatus:Array.from(document.querySelectorAll('.save-status')).map(e=>['Connecting to local service','Saving locally…','Local service disconnected','Local save failed','Saved locally · waiting for hub','Saved locally · synced'].includes(e.textContent)?e.textContent:'other'),pairInputPresent:Boolean(document.querySelector('input[autocomplete="one-time-code"]')),pairButtonDisabled:Array.from(document.querySelectorAll('button')).some(b=>b.textContent==='Connecting…' && b.disabled),expiredAlertVisible:document.body?.textContent.includes('The pairing code is incorrect or expired. Generate a new code on the desktop.')??false})
   window.__pardnerFullPairObserver={snapshot:state}
   for(const name of ['load','pageshow','pagehide','popstate'])window.addEventListener(name,()=>send(name,state()))
   send('document-entry',{hasPair:hasPair(),credentialPresent:credentialPresent()})
   window.addEventListener('hashchange',()=>send('hashchange',state()))
   const replace=history.replaceState.bind(history)
   history.replaceState=(...args)=>{const before=hasPair();const result=replace(...args);send('replace-state',{hadPair:before,hasPair:hasPair()});return result}
   for(const name of ['setItem','removeItem']){
    const original=Storage.prototype[name]
    Storage.prototype[name]=function(key,...args){const result=original.call(this,key,...args);if(String(key).endsWith(':credential'))send('credential-'+name,{credentialPresent:credentialPresent()});return result}
   }
   const fetcher=window.fetch.bind(window)
   window.fetch=async (...args)=>{
    let pathname='unknown';try{pathname=new URL(typeof args[0]==='string'?args[0]:args[0].url,location.href).pathname}catch{}
    send('fetch-start',{pathname})
    try{const result=await fetcher(...args);send('fetch-response',{pathname,status:result.status});return result}
    catch(error){send('fetch-error',{pathname,errorName:error.name});throw error}
   }
   const Original=window.WebSocket
   window.WebSocket=class extends Original{
    constructor(...args){super(...args);send('ws-created');this.addEventListener('open',()=>send('ws-open'));this.addEventListener('close',event=>send('ws-close',{code:event.code}));this.addEventListener('error',()=>send('ws-error'));this.addEventListener('message',event=>{try{const m=JSON.parse(event.data);send('ws-message',{hasDoc:Boolean(m.doc),hasStatus:Boolean(m.status),savedLocally:m.status?.savedLocally??null,syncPending:m.status?.syncPending??null,storageError:Boolean(m.status?.storageError)})}catch{send('ws-non-json')}})}
   }
   let previous=''
   const observe=()=>{const next=state(),key=JSON.stringify(next);if(key!==previous){previous=key;send('render-state',next)}}
   new MutationObserver(observe).observe(document,{subtree:true,childList:true,attributes:true,characterData:true})
   window.addEventListener('DOMContentLoaded',()=>{send('dom-content-loaded');observe()})
   window.addEventListener('beforeunload',()=>send('before-unload',state()))
    })
    context.on('page',page=>{
     const p={id:++pageId,requests:new Map(),gotos:new Map(),browserState:null,lastRender:null,lastSocket:null,lastNavigation:null,lastLoad:null};pages.set(page,p)
     let requestId=0,gotoId=0,waitId=0,frameId=0;const requests=new WeakMap(),frames=new WeakMap()
     const frame=()=>{const f=page.mainFrame();if(!frames.has(f))frames.set(f,++frameId);return {frameId:frames.get(f),...safeUrl(f.url())}}
     const current=()=>({frame:frame(),pendingGotos:[...p.gotos.values()],pendingRequests:[...p.requests.values()],browserState:p.browserState,lastRender:p.lastRender,lastSocket:p.lastSocket,lastNavigation:p.lastNavigation,lastLoad:p.lastLoad})
     const log=event=>emit({source:'driver',browserId:bid,pageId:p.id,...event})
     const goto=page.goto.bind(page)
     page.goto=(...args)=>{
      const id=++gotoId;p.gotos.set(id,{id,...safeUrl(args[0])});log({phase:'goto-start',id,target:safeUrl(args[0]),frame:frame()})
      const promise=goto(...args)
      void promise.then(()=>{p.gotos.delete(id);log({phase:'goto-resolved',id,frame:frame()})},error=>{p.gotos.delete(id);log({phase:'goto-rejected',id,errorName:error.name,frame:frame()})}).catch(()=>{})
      return promise
     }
     const getByText=page.getByText.bind(page)
     page.getByText=(...args)=>{
      const locator=getByText(...args)
      if(args[0]!=='Saved locally · synced'||args[1]?.exact!==true)return locator
      const waitFor=locator.waitFor.bind(locator)
      locator.waitFor=(...options)=>{
       const id=++waitId,timeout=options[0]?.timeout??null;log({phase:'saved-locator-start',id,timeout,state:current()})
       const promise=waitFor(...options)
       void promise.then(()=>log({phase:'saved-locator-resolved',id,timeout,state:current()}),error=>{
        log({phase:'saved-locator-rejected',id,timeout,errorName:error.name,navigationWaitReported:String(error.message).includes('navigation to finish'),state:current()})
        let timer
        const capture=Promise.race([
         page.evaluate(()=>window.__pardnerFullPairObserver?.snapshot()??{observerPresent:false}).then(state=>log({phase:'failure-browser-snapshot',id,state}),error=>log({phase:'failure-browser-snapshot-error',id,errorName:error.name})),
         new Promise(resolve=>{timer=setTimeout(()=>{log({phase:'failure-browser-snapshot-deadline',id});resolve()},1000)})
        ]).finally(()=>{clearTimeout(timer);pendingCaptures.delete(capture)})
        pendingCaptures.add(capture)
       }).catch(()=>{})
       return promise
      }
      return locator
     }
     page.on('request',req=>{const id=++requestId;requests.set(req,id);const r={id,method:req.method(),...safeUrl(req.url()),navigation:req.isNavigationRequest()};delete r.hasPair;p.requests.set(id,r);log({phase:'request',...r})})
     page.on('response',res=>log({phase:'response',id:requests.get(res.request()),pathname:safeUrl(res.url()).pathname,status:res.status()}))
     page.on('requestfinished',req=>{const id=requests.get(req);p.requests.delete(id);log({phase:'request-finished',id,pathname:safeUrl(req.url()).pathname})})
     page.on('requestfailed',req=>{const id=requests.get(req);p.requests.delete(id);log({phase:'request-failed',id,pathname:safeUrl(req.url()).pathname})})
     page.on('framenavigated',f=>{if(f!==page.mainFrame())return;p.lastNavigation={at:Date.now(),...frame()};log({phase:'navigation',...p.lastNavigation})})
     for(const name of ['domcontentloaded','load'])page.on(name,()=>{p.lastLoad={at:Date.now(),event:name,...frame()};log({phase:name,...p.lastLoad})})
     page.on('pageerror',error=>log({phase:'page-error',errorName:error.name}))
    })
    return context
   }
   const close=browser.close.bind(browser)
   browser.close=(...args)=>{
    const finish=promise=>{void promise.then(()=>flush(),()=>flush());return promise}
    // Snapshot capture only delays failure cleanup, never the original locator promise.
    if(pendingCaptures.size)return finish(Promise.allSettled([...pendingCaptures]).then(()=>close(...args)))
    return finish(close(...args))
   }
   return browser
  }
 }
}
